scripts:
(function(){
  function css(v){ return getComputedStyle(document.documentElement).getPropertyValue(v).trim(); }
  var ns = 'http://www.w3.org/2000/svg';
  function el(tag, attrs){ var e=document.createElementNS(ns,tag); for(var k in attrs) e.setAttribute(k, attrs[k]); return e; }

  // tariff mention bar chart
  (function(){
    var svg = document.getElementById('chart-tariff');
    if(!svg) return;
    var data = [
      {l:"23 Q3",v:0},{l:"23 Q4",v:0},{l:"24 Q1",v:0},{l:"24 Q2",v:0},{l:"24 Q3",v:0},
      {l:"24 Q4",v:2},{l:"25 Q1",v:3},{l:"25 Q2",v:0},{l:"25 Q3",v:0},{l:"25 Q4",v:1},
      {l:"26 Q1",v:0},{l:"26 Q2",v:0}
    ];
    var W=780,H=190,padL=28,padR=10,padT=14,padB=30;
    var plotW=W-padL-padR, plotH=H-padT-padB;
    var n=data.length, gap=10;
    var barW=(plotW-gap*(n-1))/n;
    var max=3.4;
    svg.appendChild(el('line',{x1:padL,y1:H-padB,x2:W-padR,y2:H-padB,stroke:css('--line'),'stroke-width':1}));
    data.forEach(function(d,i){
      var x=padL+i*(barW+gap);
      var bh=(d.v/max)*plotH;
      var y=H-padB-bh;
      var color = d.v>=3 ? css('--risk') : (d.v>0 ? css('--gold') : css('--line'));
      svg.appendChild(el('rect',{x:x,y:y,width:barW,height:Math.max(bh,2),rx:3,fill:color}));
      if(d.v>0){
        var t=el('text',{x:x+barW/2,y:y-6,'text-anchor':'middle','font-size':11,'font-family':'IBM Plex Mono, monospace',fill:css('--ink-soft')});
        t.textContent=d.v;
        svg.appendChild(t);
      }
      var lbl=el('text',{x:x+barW/2,y:H-padB+15,'text-anchor':'middle','font-size':9.5,'font-family':'IBM Plex Mono, monospace',fill:css('--ink-soft')});
      lbl.textContent=d.l;
      svg.appendChild(lbl);
    });
    var title=el('text',{x:padL,y:12,'font-size':10.5,'font-family':'IBM Plex Mono, monospace',fill:css('--ink-soft')});
    title.textContent="어닝콜 스크립트 내 'tariff' 언급 횟수";
    svg.appendChild(title);
  })();

  // confidence line chart
  (function(){
    var svg = document.getElementById('chart-confidence');
    if(!svg) return;
    var data = [
      {l:"23 Q3",v:6,note:"지정학 충격, 신중한 톤"},
      {l:"23 Q4",v:6,note:"균형 잡힌 tailwind/headwind"},
      {l:"24 Q1",v:7,note:"가이던스 재확인"},
      {l:"24 Q2",v:7,note:"조직개편, 광범위한 모멘텀"},
      {l:"24 Q3",v:8,note:"\"무서울 것 없다\", M&A 발표"},
      {l:"24 Q4",v:7,note:"관세 질문 첫 등장"},
      {l:"25 Q1",v:6,note:"CEO, 관세발 심리 위축 인정"},
      {l:"25 Q2",v:8,note:"가이던스 상단으로 상향"},
      {l:"25 Q3",v:8,note:"\"시장 선도 혁신\" 지속"},
      {l:"25 Q4",v:7,note:"전략적 검토·조직 재편 시사"},
      {l:"26 Q1",v:6,note:"성장 둔화, 국경간 여행 압박"},
      {l:"26 Q2",v:6,note:"CFO 교체 발표"}
    ];
    var W=800,H=260,padL=34,padR=16,padT=20,padB=70;
    var plotW=W-padL-padR, plotH=H-padT-padB;
    var n=data.length;
    var stepX = plotW/(n-1);
    var minV=1, maxV=10;
    function yFor(v){ return padT + plotH - ((v-minV)/(maxV-minV))*plotH; }
    function xFor(i){ return padL + i*stepX; }

    // gridlines
    [2,4,6,8,10].forEach(function(gv){
      var y=yFor(gv);
      svg.appendChild(el('line',{x1:padL,y1:y,x2:W-padR,y2:y,stroke:css('--line'),'stroke-width':1,'stroke-dasharray':'3,4'}));
      var t=el('text',{x:padL-8,y:y+3,'text-anchor':'end','font-size':10,'font-family':'IBM Plex Mono, monospace',fill:css('--ink-soft')});
      t.textContent=gv;
      svg.appendChild(t);
    });

    var pts = data.map(function(d,i){ return xFor(i)+','+yFor(d.v); }).join(' ');
    svg.appendChild(el('polyline',{points:pts, fill:'none', stroke:css('--blue'), 'stroke-width':2.5, 'stroke-linejoin':'round','stroke-linecap':'round'}));

    data.forEach(function(d,i){
      var x=xFor(i), y=yFor(d.v);
      var flag = (d.l==="25 Q1" || d.l==="26 Q1" || d.l==="26 Q2");
      svg.appendChild(el('circle',{cx:x,cy:y,r:5,fill: flag? css('--risk'):css('--blue'), stroke:css('--paper'),'stroke-width':2}));
      var lbl=el('text',{x:x,y:H-padB+16,'text-anchor':'middle','font-size':9.5,'font-family':'IBM Plex Mono, monospace',fill:css('--ink-soft')});
      lbl.textContent=d.l;
      svg.appendChild(lbl);
      var note=el('text',{x:x,y:H-padB+30, 'text-anchor':'middle','font-size':8.7,'font-family':'IBM Plex Sans, sans-serif',fill:css('--ink-soft')});
      // wrap note into two lines if long
      var words = d.note.split(' ');
      var line1='', line2='';
      words.forEach(function(w){ if((line1+w).length<10 && line2==='') line1+=w+' '; else line2+=w+' '; });
      var tsp1 = document.createElementNS(ns,'tspan'); tsp1.setAttribute('x',x); tsp1.setAttribute('dy','0'); tsp1.textContent=line1.trim();
      var tsp2 = document.createElementNS(ns,'tspan'); tsp2.setAttribute('x',x); tsp2.setAttribute('dy','11'); tsp2.textContent=line2.trim();
      note.appendChild(tsp1); note.appendChild(tsp2);
      svg.appendChild(note);
    });
  })();
})();
